<script setup>import{onMounted,reactive,ref,watch}from'vue';import{useRoute}from'vue-router';import{showSuccessToast}from'vant';import{api}from'../api/crm';const route=useRoute(),items=ref([]),keyword=ref(''),show=ref(false),loading=ref(false);const blank=()=>({name:'',shortName:'',industry:'',level:'B',status:'LEAD',source:'',phone:'',email:'',address:'',nextFollowUpDate:'',notes:''});const form=reactive(blank());const statusLabel={LEAD:'潜在线索',FOLLOWING:'持续跟进',CUSTOMER:'成交客户',INACTIVE:'暂不跟进'};async function load(){loading.value=true;try{items.value=await api.customers(keyword.value)}finally{loading.value=false}}async function create(){await api.createCustomer({...form,nextFollowUpDate:form.nextFollowUpDate||null});Object.assign(form,blank());show.value=false;showSuccessToast('客户已创建');load()}let timer;watch(keyword,()=>{clearTimeout(timer);timer=setTimeout(load,250)});onMounted(()=>{load();show.value=route.query.create==='1'})</script>
<template><div class="page safe-top"><div class="title-row"><h1 class="page-title">客户</h1><van-button size="small" round color="#2856a8" icon="plus" @click="show=true">新增</van-button></div><van-search v-model="keyword" shape="round" placeholder="搜索客户名称或行业"/><section v-for="item in items" :key="item.id" class="customer card" @click="$router.push(`/customers/${item.id}`)"><div class="level" :class="`l-${item.level.toLowerCase()}`">{{item.level}}</div><div class="info"><div class="list-title">{{item.shortName||item.name}}</div><div class="muted name">{{item.name}}</div><div class="meta"><span class="tag">{{statusLabel[item.status]}}</span><span>{{item.industry||'未设置行业'}}</span><span>负责人 {{item.ownerName}}</span></div></div><van-icon name="arrow" color="#a8b0bc"/></section><div v-if="!loading&&!items.length" class="empty">暂无客户，点击右上角新增</div><van-popup v-model:show="show" position="bottom" round :style="{height:'88%'}"><div class="form"><h2>新增客户</h2><van-field v-model="form.name" label="客户名称" required placeholder="企业或客户全称"/><van-field v-model="form.shortName" label="客户简称"/><van-field v-model="form.industry" label="所属行业"/><div class="inline-label">客户等级</div><van-radio-group v-model="form.level" direction="horizontal"><van-radio v-for="x in ['A','B','C','D']" :key="x" :name="x">{{x}}</van-radio></van-radio-group><div class="inline-label">客户状态</div><van-radio-group v-model="form.status" direction="horizontal"><van-radio name="LEAD">线索</van-radio><van-radio name="FOLLOWING">跟进</van-radio><van-radio name="CUSTOMER">成交</van-radio></van-radio-group><van-field v-model="form.source" label="客户来源"/><van-field v-model="form.phone" label="联系电话" type="tel"/><van-field v-model="form.email" label="电子邮箱"/><van-field v-model="form.address" label="地址"/><van-field v-model="form.nextFollowUpDate" label="下次跟进" type="date"/><van-field v-model="form.notes" label="备注" type="textarea" rows="2"/><button class="action-btn" :disabled="!form.name" @click="create">保存客户</button></div></van-popup></div></template>
<style scoped>.title-row{display:flex;align-items:center;justify-content:space-between}.van-search{padding:0 0 15px;background:transparent}.customer{display:flex;align-items:center;gap:12px}.level{width:40px;height:40px;border-radius:13px;display:grid;place-items:center;font-weight:800;background:#e9eef8;color:#2856a8}.l-a{background:#fff0df;color:#bd6817}.l-c,.l-d{background:#edf0f4;color:#7b8697}.info{flex:1;min-width:0}.name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.meta{display:flex;gap:9px;align-items:center;margin-top:9px;color:#8a96a8;font-size:11px}.form{padding:18px 20px 32px;overflow:auto}.form h2{margin:0 0 10px}.inline-label{font-size:14px;color:#646b75;padding:14px 16px 8px}.van-radio-group{padding:0 16px 10px;gap:15px}.action-btn{margin-top:14px}</style>
